import type { HTTPError } from "../../error.ts";

export const kProblem: unique symbol = /* @__PURE__ */ Symbol.for("h3.internal.problem") as any;

export interface ProblemMeta {
  type: string;
  title?: string;
  detail?: string;
  instance?: string;
}

export function problemBody(
  error: HTTPError,
  meta: ProblemMeta,
  debug?: boolean,
): Record<string, unknown> {
  const stack = debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined;
  if (error.unhandled) {
    return { type: meta.type, title: meta.title, status: error.status, stack };
  }
  return {
    ...(error.data === undefined ? undefined : { data: error.data }),
    ...error.body,
    type: meta.type,
    title: meta.title,
    status: error.status,
    detail: meta.detail,
    instance: meta.instance,
    stack,
  };
}

